/**
 * Opens the on-device database and applies the bundled Drizzle migrations
 * (`src/db/migrations`, generated by `npx drizzle-kit generate`). Started once
 * at app launch from the root layout; anything that reads or writes SQLite
 * awaits the same promise first. A failure is reported to the sync store and
 * the next call tries again. It never blocks sign-in: every online screen
 * keeps working, and only the Sell screen shows the error.
 */
import { migrate } from 'drizzle-orm/expo-sqlite/migrator';

import { getDb } from '@/db/client';
import { readCatalogueSummary } from '@/db/menuQueries';
import migrations from '@/db/migrations/migrations';
import { captureError } from '@/errors/capture';
import { useSyncStore } from '@/stores/sync';

export const DATABASE_ERROR_MESSAGE = "The menu stored on this device couldn't be opened. Restart the app and try again.";

let preparing: Promise<boolean> | null = null;

/** Resolves `true` once the database is migrated and ready, `false` if that failed. Never rejects. */
export function prepareDatabase(): Promise<boolean> {
  if (preparing) return preparing;

  preparing = (async () => {
    try {
      await migrate(getDb(), migrations);
      const summary = await readCatalogueSummary();
      useSyncStore.getState().setDatabaseReady(summary.serverTime);
      return true;
    } catch (error) {
      // Phase 8 §F: a failed migration of the local database goes to the error log (held in memory).
      captureError(error, { level: 'error', extra: { source: 'sqlite_migration' } });
      useSyncStore.getState().setDatabaseError(DATABASE_ERROR_MESSAGE);
      preparing = null;
      return false;
    }
  })();

  return preparing;
}
